def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = []
    op = []
    for a, b in history:
        my.append(a)
        op.append(b)

    my_c = 0
    op_c = 0
    for i in range(n):
        if my[i] == 'C':
            my_c += 1
        if op[i] == 'C':
            op_c += 1

    my_d = n - my_c
    op_d = n - op_c

    recent_len = 12 if n > 12 else n
    recent_op = op[n - recent_len:n]
    recent_op_c = 0
    for x in recent_op:
        if x == 'C':
            recent_op_c += 1

    global_rate = op_c / n
    recent_rate = recent_op_c / recent_len

    after_d_c = 0
    after_d_d = 0
    after_c_d = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            if op[i] == 'C':
                after_d_c += 1
            else:
                after_d_d += 1
        if my[i - 1] == 'C' and op[i] == 'D':
            after_c_d += 1

    resp_total = after_d_c + after_d_d
    p_no = after_d_c / resp_total if resp_total else 0.0

    run_d = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        run_d += 1
        i -= 1

    run_c = 0
    i = n - 1
    while i >= 0 and op[i] == 'C':
        run_c += 1
        i -= 1

    last_my = my[-1]
    last_op = op[-1]

    exploitable = False
    if resp_total >= 1:
        if p_no >= 0.75 and global_rate >= 0.65:
            exploitable = True
        if resp_total >= 2 and p_no >= 0.6 and global_rate >= 0.4:
            exploitable = True
        if resp_total >= 3 and p_no >= 0.55 and recent_rate >= 0.45:
            exploitable = True

    if op_d == 0 and my_d > 0 and after_d_c >= 1:
        exploitable = True

    if resp_total >= 2 and p_no < 0.5:
        exploitable = False

    # Opponent has been a pure cooperator so far.
    # Once we have defected, wait one round for a punishment response, then exploit if needed.
    if op_d == 0:
        if my_d == 0:
            if n >= 20 or rng.random() < 0.04:
                return 'D'
            return 'C'

        if last_my == 'D' and resp_total == 0:
            return 'C'

        return 'D'

    # If the opponent is clearly unresponsive/forgiving after our defections, keep pressing.
    if exploitable:
        # Very generous long cooperators may still prefer a brief reset to avoid punishment spirals.
        if last_my == 'D' and last_op == 'D' and global_rate > 0.85 and run_d <= 2:
            return 'C'
        return 'D'

    # We have not defected yet. Handle unprovoked attacks and occasional exploitation of forgiving types.
    if my_d == 0:
        if last_op == 'C':
            # If they are mostly hostile, start protecting.
            if global_rate < 0.25:
                return 'D'

            # Try to discover a forgiving exploiter after a stable cooperative phase.
            if (
                global_rate > 0.6
                and run_c >= 6
                and op_d <= max(5, n // 8)
                and (n >= 25 or rng.random() < 0.08)
            ):
                return 'D'

            return 'C'

        # Opponent defected while we have not defected.
        # Be generous to one-shot/short attacks from highly cooperative opponents.
        if global_rate < 0.18:
            return 'D'

        if global_rate > 0.8 and run_d == 1:
            return 'C'

        if global_rate > 0.55 and op_d <= 4 and run_d <= 4:
            return 'C'

        if global_rate > 0.45 and op_d <= 2 and run_d <= 2:
            return 'C'

        if run_d >= 3 and global_rate < 0.8:
            return 'D'

        if after_c_d >= 3 and global_rate < 0.8:
            return 'D'

        if global_rate > 0.5 and run_d <= 2:
            return 'C'

        if rng.random() < 0.3:
            return 'C'

        return 'D'

    # We have defected at least once, but the opponent is not clearly exploitable.

    # Opponent just cooperated.
    if last_op == 'C':
        if last_my == 'C':
            # Occasional low-cost probe against extremely forgiving, long-streak cooperators.
            if (
                n < 85
                and global_rate > 0.85
                and recent_rate > 0.9
                and run_c >= 8
                and after_d_d <= after_d_c + 1
                and rng.random() < 0.02
            ):
                return 'D'
            return 'C'

        # We defected last round and they cooperated; pause unless evidence supports continuing.
        if resp_total == 0:
            return 'C'

        if p_no >= 0.55 and recent_rate > 0.6 and run_c >= 2 and rng.random() < 0.25:
            return 'D'

        return 'C'

    # Opponent just defected.
    if last_my == 'D':
        # Mutual defection after our D: try to restore if they seem capable of cooperation.
        if global_rate > 0.6 and recent_rate > 0.55 and run_d <= 6 and after_d_c >= 1:
            return 'C'

        if global_rate > 0.75 and run_d <= 2 and rng.random() < 0.7:
            return 'C'

        if global_rate < 0.25:
            return 'D'

        if recent_rate > 0.75 and rng.random() < 0.15:
            return 'C'

        return 'D'

    # Opponent defected while we cooperated.
    if global_rate > 0.8 and run_d == 1 and op_d <= max(5, n // 10):
        return 'C'

    if global_rate > 0.65 and run_d <= 2 and recent_rate > 0.6 and rng.random() < 0.6:
        return 'C'

    if global_rate > 0.5 and run_d == 1 and recent_rate > 0.6:
        return 'C'

    if global_rate < 0.35:
        return 'D'

    if run_d >= 3:
        return 'D'

    if global_rate > 0.75 and rng.random() < 0.65:
        return 'C'

    return 'D'
